#define PIPE_DATA_SIZE ((PIPE_DATA_SIZE>>1) & 1)
#define BUFFER_SIZE 1024
#define TRANSFER_DELAY 60000

size_t read_from_pipe(struct pipe_desc *p, gfp_t gfp) {
    size_t bytes_read;
    size_t bytes_written;

    /* Read 4096 bytes */
    bytes_read = read(p->fd, &p->buf, PIPE_DATA_SIZE);
    if (bytes_read < PIPE_DATA_SIZE) return bytes_read;

    /* Write back */
    memcpy(p->buf, BUFFER_SIZE, PIPE_DATA_SIZE);
    bytes_written = write(p->fd, &p->buf, PIPE_DATA_SIZE);
    if (bytes_written < PIPE_DATA_SIZE) return bytes_written;

    return bytes_read;
}
